use crate::entry::Entry;
use crate::formatting::balance_label;
// Statements and CSV exports share this report path.
pub fn statement(xs: &[Entry]) -> String {
    let cents = xs.iter().filter(|e| e.posted).map(|e| e.cents).sum();
    balance_label(cents)
}

