use fixture_ledger::{entry::{Entry, Kind}, ledger, report, export};
#[test]
fn posted_charge_workflow() {
    let xs = [Entry { kind: Kind::Charge, cents: 40, posted: true }];
    assert_eq!(ledger::balance(&xs), 40);
    assert_eq!(report::statement(&xs), "balance=40");
    assert!(export::csv("demo", &xs).contains("balance=40"));
}

