#[derive(Clone, Copy)]
pub enum Kind { Charge, Refund }
pub struct Entry { pub kind: Kind, pub cents: i64, pub posted: bool }
pub fn delta(e: &Entry) -> i64 { match e.kind { Kind::Charge => e.cents, Kind::Refund => -e.cents } }

